/**
 * Sequence integerizer — PLAN.md §5 row 0 / §8 Encoding.
 *
 * Maps string-labelled sequences to flat `Int32Array` indices via the
 * caller's canonical `labels` array. Index `k` always means `labels[k]`.
 *
 * Cardinal rules (do NOT relax without re-reading PLAN.md §8):
 *  - The label set is INPUT, not derived from the sequences. A state in
 *    `labels` with zero observations keeps its index; a sequence value not
 *    in `labels` is an error (or maps to sentinel −2 if explicitly enabled).
 *  - Sentinels: −1 for NA (TS marker `\0__NA__` + any caller `naSyms`), −2
 *    for "unknown value, allowed through" (per-kernel opt-in).
 */

export const NA_SENTINEL = -1 as const;
export const UNKNOWN_SENTINEL = -2 as const;
/** TS-side marker used by reference/core/transitions.ts. Mirrored verbatim. */
export const TNAJ_NA_MARKER = '\0__NA__' as const;

export interface IntegerizeOptions {
  /** Extra strings to treat as NA, in addition to TNAJ_NA_MARKER. */
  naSyms?: readonly string[];
  /**
   * What to do when a sequence value is not in `labels` and not in `naSyms`.
   * - 'error' (default): throw. Catches typo'd labels and split-state bugs.
   * - 'sentinel': emit `UNKNOWN_SENTINEL` (−2). Per-kernel opt-in.
   */
  onUnknown?: 'error' | 'sentinel';
  /** Also treat `null`, `undefined`, and the empty string as NA. Default: true. */
  emptyIsNa?: boolean;
}

export interface IntegerizedSequences {
  /** Flat indices for all rows, concatenated. */
  values: Int32Array;
  /** Length n+1: rowStarts[i]..rowStarts[i+1] gives the index range of row i. */
  rowStarts: Uint32Array;
  /** Same labels array passed in (NOT a copy — caller owns it). */
  labels: readonly string[];
  /** Number of input sequences (== rowStarts.length − 1). */
  nSequences: number;
  /** Total integers emitted (== values.length, == rowStarts[n]). */
  totalLength: number;
}

/**
 * Build an integerized representation of `sequences` against `labels`.
 *
 * @param sequences Jagged array of rows; each cell is a state label (string),
 *                  or null/undefined/empty (NA when `emptyIsNa`), or one of
 *                  the configured NA markers.
 * @param labels Caller's canonical label order. **Pass `model.labels` from the
 *               TNA model** — do not derive from the sequences themselves.
 * @param opts See `IntegerizeOptions`.
 *
 * @throws Error if `onUnknown === 'error'` and an unknown value is seen.
 */
export function integerize(
  sequences: readonly (readonly (string | null | undefined)[])[],
  labels: readonly string[],
  opts: IntegerizeOptions = {},
): IntegerizedSequences {
  const { naSyms = [], onUnknown = 'error', emptyIsNa = true } = opts;

  // Pre-build the lookup so each step is O(1). Map<string, number> here is
  // hot-path acceptable for our typical label-set sizes (≤ ~100 states).
  const labelToIdx = new Map<string, number>();
  for (let i = 0; i < labels.length; i++) {
    const lbl = labels[i]!;
    if (labelToIdx.has(lbl)) {
      throw new Error(`integerize: duplicate label in labels[]: ${JSON.stringify(lbl)}`);
    }
    labelToIdx.set(lbl, i);
  }
  const naSet = new Set<string>([TNAJ_NA_MARKER, ...naSyms]);

  const n = sequences.length;
  const rowStarts = new Uint32Array(n + 1);
  let total = 0;
  for (let i = 0; i < n; i++) {
    rowStarts[i] = total;
    total += sequences[i]!.length;
  }
  rowStarts[n] = total;

  const values = new Int32Array(total);
  for (let i = 0; i < n; i++) {
    const row = sequences[i]!;
    const base = rowStarts[i]!;
    for (let j = 0; j < row.length; j++) {
      const cell = row[j];
      // NA path
      if (cell === null || cell === undefined) {
        if (emptyIsNa) {
          values[base + j] = NA_SENTINEL;
          continue;
        }
        // Fall through to onUnknown handling — null/undefined treated as
        // "unknown" rather than NA. Edge case; documenting for completeness.
      }
      const s = typeof cell === 'string' ? cell : String(cell);
      if (emptyIsNa && s === '') {
        values[base + j] = NA_SENTINEL;
        continue;
      }
      if (naSet.has(s)) {
        values[base + j] = NA_SENTINEL;
        continue;
      }
      const idx = labelToIdx.get(s);
      if (idx !== undefined) {
        values[base + j] = idx;
        continue;
      }
      if (onUnknown === 'sentinel') {
        values[base + j] = UNKNOWN_SENTINEL;
        continue;
      }
      throw new Error(
        `integerize: sequence[${i}][${j}] = ${JSON.stringify(s)} is not in labels and not configured as NA. ` +
          `Pass it via naSyms or use onUnknown: "sentinel" to map to the −2 reserved index.`,
      );
    }
  }

  return {
    values,
    rowStarts,
    labels,
    nSequences: n,
    totalLength: total,
  };
}
