/**
 * passageTime, markovStability, markovOrderTest — WASM-backed.
 * Result shapes match tnaj exactly, including the Matrix wrapper around
 * the MFPT matrix.
 */
import { passageTimeWasm, markovStabilityWasm, markovOrderTestWasm } from '../wasm-engine/index-pure.js';
// Matrix from tnaj/core, NOT 'tnaj' root: importing from the root pulls in
// tnaj's full barrel and (without `"sideEffects": false` on the upstream
// package) drags `tnaj/analysis/markov.ts` along, which contains the
// pure-TS markovOrderTest / passageTime / markovStability we deliberately
// excluded from tnaj-light. Deep import keeps the bundle clean.
import { Matrix } from '../core/index.js';
import type {
  MarkovInput,
  MarkovOrderInput,
  MarkovOrderOptions,
  MarkovOrderResult,
  MarkovStabilityResult,
  MarkovStabilityRow,
  PassageTimeOptions,
  PassageTimeResult,
  TNA,
} from '../index.js';
import { integerize } from '../wasm-engine/index-pure.js';
import { assertReady } from './assert.js';

function extractMatrixFromInput(x: MarkovInput): { mat: Float64Array; labels: string[]; n: number } {
  // Mirror tnaj's extractP. Three input forms: TNA, Matrix, number[][].
  if (x instanceof Matrix) {
    const n = x.rows;
    const mat = new Float64Array(n * n);
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) mat[i * n + j] = x.get(i, j);
    return { mat, labels: Array.from({ length: n }, (_, i) => `S${i}`), n };
  }
  if (Array.isArray(x)) {
    const n = x.length;
    const mat = new Float64Array(n * n);
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) mat[i * n + j] = x[i]![j]!;
    return { mat, labels: Array.from({ length: n }, (_, i) => `S${i}`), n };
  }
  // TNA
  const t = x as TNA;
  const n = t.labels.length;
  const mat = new Float64Array(n * n);
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) mat[i * n + j] = t.weights.get(i, j);
  return { mat, labels: [...t.labels], n };
}

export function passageTime(x: MarkovInput, options: PassageTimeOptions = {}): PassageTimeResult {
  assertReady();
  const { normalize = true } = options;
  const { mat, labels, n } = extractMatrixFromInput(x);
  const r = passageTimeWasm({ p: mat, nStates: n, normalize });
  // Pack flat n*n back into a tnaj Matrix.
  const M = Matrix.zeros(n, n);
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) M.set(i, j, r.mfpt[i * n + j]!);
  // Optional `states` subset filter (mirror tnaj behaviour).
  if (options.states) {
    const idx = options.states.map((s) => {
      const k = labels.indexOf(s);
      if (k < 0) throw new Error(`passageTime: state ${s} not in labels`);
      return k;
    });
    const sub = Matrix.zeros(idx.length, idx.length);
    const stationary = new Float64Array(idx.length);
    const persistence = new Float64Array(idx.length);
    for (let a = 0; a < idx.length; a++) {
      stationary[a] = r.stationary[idx[a]!]!;
      persistence[a] = r.persistence[idx[a]!]!;
      for (let b = 0; b < idx.length; b++) sub.set(a, b, M.get(idx[a]!, idx[b]!));
    }
    return { matrix: sub, stationary, persistence, states: options.states };
  }
  return { matrix: M, stationary: r.stationary, persistence: r.persistence, states: labels };
}

export function markovStability(
  x: MarkovInput,
  options: { normalize?: boolean } = {},
): MarkovStabilityResult {
  assertReady();
  const { normalize = true } = options;
  const { mat, labels, n } = extractMatrixFromInput(x);
  const r = markovStabilityWasm({ p: mat, nStates: n, normalize });
  const M = Matrix.zeros(n, n);
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) M.set(i, j, r.mfpt[i * n + j]!);
  const stability: MarkovStabilityRow[] = r.rows.map((row, i) => ({
    state: labels[i]!,
    persistence: row.persistence,
    stationaryProb: row.stationaryProb,
    returnTime: row.returnTime,
    sojournTime: row.sojournTime,
    avgTimeToOthers: row.avgTimeToOthers,
    avgTimeFromOthers: row.avgTimeFromOthers,
  }));
  return { stability, mpt: { matrix: M, stationary: r.stationary, persistence: r.persistence, states: labels } };
}

export function markovOrderTest(
  data: MarkovOrderInput,
  options: MarkovOrderOptions = {},
): MarkovOrderResult {
  assertReady();
  const { maxOrder = 3, nPerm = 500, alpha = 0.05, seed = 42 } = options;

  // Convert input to integerized form. MarkovOrderInput can be a sequence
  // array or a TNA model with data. `labels` (i32 index → string) is kept
  // local so we can map kernel-returned state indices back to label names
  // for the fitted transitionMatrices / transitionNodes.
  let values: Int32Array;
  let rowStarts: Uint32Array;
  let labels: readonly string[];
  if (Array.isArray(data)) {
    const seqs = data as readonly (readonly (string | null)[])[];
    const labelSet = new Set<string>();
    for (const seq of seqs) for (const v of seq) if (v != null) labelSet.add(v);
    labels = [...labelSet].sort();
    const ig = integerize(seqs, labels);
    values = ig.values;
    rowStarts = ig.rowStarts;
  } else {
    const tna = data as TNA;
    if (!tna.data) throw new Error('markovOrderTest: TNA model missing data');
    const seqs = tna.data as unknown as readonly (readonly (string | null)[])[];
    labels = tna.labels;
    const ig = integerize(seqs, labels);
    values = ig.values;
    rowStarts = ig.rowStarts;
  }

  const r = markovOrderTestWasm({ values, rowStarts, maxOrder, nPerm, alpha, seed });

  // tnaj's testTable rows have `order, loglik, df, g2, aic, bic, pPermutation, pAsymptotic`.
  // WASM returns identically-shaped rows. Remap field casing: WASM shim
  // uses lowercase aic/bic, tnaj uses AIC/BIC.
  const testTable = r.testTable.map((t) => ({
    order: t.order,
    loglik: t.loglik,
    AIC: t.aic,
    BIC: t.bic,
    df: t.df,
    g2: t.g2,
    pPermutation: t.pPermutation,
    pAsymptotic: t.pAsymptotic,
    significant: t.significant,
  }));

  // Repack fitted models. Order 0 is the marginal stored as a 1×n_0 Matrix
  // (matches tnaj's convention). Orders 1..K are n_k × n_k.
  // tnaj joins k-gram tokens with HON_SEP = '\x01'.
  const HON_SEP = '\x01';
  const transitionMatrices: Matrix[] = r.transitionMatrices.map((buf, k) => {
    const nk = r.transitionNodes[k]!.length;
    if (k === 0) {
      const m = Matrix.zeros(1, nk);
      for (let j = 0; j < nk; j++) m.set(0, j, buf[j]!);
      return m;
    }
    const m = Matrix.zeros(nk, nk);
    for (let i = 0; i < nk; i++) {
      for (let j = 0; j < nk; j++) {
        m.set(i, j, buf[i * nk + j]!);
      }
    }
    return m;
  });
  const transitionNodes: string[][] = r.transitionNodes.map((nodesAtOrder, k) =>
    nodesAtOrder.map((tup) => {
      // Map each state index in the tuple back to the label string.
      const parts = tup.map((idx) => {
        const s = labels[idx];
        if (s === undefined) {
          throw new Error(
            `markovOrderTest: kernel emitted unknown state index ${idx} at order ${k}`,
          );
        }
        return s;
      });
      return k === 0 ? parts[0]! : parts.join(HON_SEP);
    }),
  );
  // Marginal labels + probs (order-0 view). The kernel may emit only states
  // that appear in the data, so these can be a subset of `labels`.
  const states = transitionNodes[0]!.slice();
  const marginal = new Float64Array(r.transitionMatrices[0]!);

  const result: MarkovOrderResult = {
    optimalOrder: r.optimalOrder,
    bicOrder: r.bicOrder,
    aicOrder: r.aicOrder,
    testTable,
    permutationNull: r.permutationNull,
    logliks: testTable.map((t) => t.loglik),
    layerDofs: testTable.map((t) => t.df),
    transitionMatrices,
    transitionNodes,
    states,
    marginal,
    nSequences: r.nSequences,
    nObservations: r.nObservations,
    nTuples: r.nTuples,
    nPerm,
    alpha,
    maxOrder,
  };
  return result;
}
