/**
 * Target-agnostic readiness check. Imports ONLY from
 * `tnaj-wasm-engine/shared` so neither pkg/ (nodejs) nor pkg-web/ (web)
 * is pulled into the importing bundle. The actual init module (init.ts
 * for node, init-web.ts for browser) registers exports via load-shared
 * state; this file just queries it.
 */
import { isInitialized } from '../wasm-engine/load-shared.js';

export function assertReady(): void {
  if (!isInitialized()) {
    throw new Error(
      'tnaw: WASM engine not initialized. Call `await initTnaw()` before any tnaw function.',
    );
  }
}
