/**
 * reliabilityAnalysis — WASM-backed. Split-half pipeline matching tnaj's
 * ReliabilityResult shape.
 *
 * Scope: v0 supports modelType in {'tna', 'ftna'}. The Rust kernel
 * computes per-sequence transitions then aggregates per-half. atna and
 * ctna use different transition arithmetic and are NOT in the WASM
 * kernel — calling tnaw.reliabilityAnalysis with those throws. Use
 * tnaj.reliabilityAnalysis for atna/ctna.
 */
import { reliabilityAnalysisWasm, integerize, RELIABILITY_METRIC_KEYS } from '../wasm-engine/index-pure.js';
import type { ReliabilityResult, SequenceData } from '../index.js';
import { assertReady } from './assert.js';

// Hardcoded copy of tnaj's RELIABILITY_METRICS list so we don't pull in
// `tnaj/analysis/reliability.ts` (which would drag analysis/bootstrap.ts,
// stability.ts, etc. via barrel evaluation). 22 entries in canonical order.
const RELIABILITY_METRICS: { key: string; label: string; category: string }[] = [
  { key: 'mad',        label: 'Mean Abs. Diff.',   category: 'Deviations' },
  { key: 'median_ad',  label: 'Median Abs. Diff.', category: 'Deviations' },
  { key: 'rmsd',       label: 'RMS Diff.',          category: 'Deviations' },
  { key: 'max_ad',     label: 'Max Abs. Diff.',     category: 'Deviations' },
  { key: 'rel_mad',    label: 'Rel. MAD',           category: 'Deviations' },
  { key: 'cv_ratio',   label: 'CV Ratio',           category: 'Deviations' },
  { key: 'pearson',    label: 'Pearson',            category: 'Correlations' },
  { key: 'spearman',   label: 'Spearman',           category: 'Correlations' },
  { key: 'kendall',    label: 'Kendall',            category: 'Correlations' },
  { key: 'dcor',       label: 'Distance Corr.',     category: 'Correlations' },
  { key: 'euclidean',  label: 'Euclidean',          category: 'Dissimilarities' },
  { key: 'manhattan',  label: 'Manhattan',          category: 'Dissimilarities' },
  { key: 'canberra',   label: 'Canberra',           category: 'Dissimilarities' },
  { key: 'braycurtis', label: 'Bray-Curtis',        category: 'Dissimilarities' },
  { key: 'frobenius',  label: 'Frobenius',          category: 'Dissimilarities' },
  { key: 'cosine',     label: 'Cosine',             category: 'Similarities' },
  { key: 'jaccard',    label: 'Jaccard',            category: 'Similarities' },
  { key: 'dice',       label: 'Dice',               category: 'Similarities' },
  { key: 'overlap',    label: 'Overlap',            category: 'Similarities' },
  { key: 'rv',         label: 'RV',                 category: 'Similarities' },
  { key: 'rank_agree', label: 'Rank Agreement',     category: 'Pattern' },
  { key: 'sign_agree', label: 'Sign Agreement',     category: 'Pattern' },
];

export function reliabilityAnalysis(
  sequenceData: SequenceData,
  modelType: 'tna' | 'ftna' | 'ctna' | 'atna',
  opts: {
    iter?: number;
    split?: number;
    atnaBeta?: number;
    seed?: number;
    scaling?: string;
    addStartState?: boolean;
    startStateLabel?: string;
    addEndState?: boolean;
    endStateLabel?: string;
  } = {},
): ReliabilityResult {
  assertReady();

  if (modelType !== 'tna' && modelType !== 'ftna') {
    throw new Error(
      `tnaw.reliabilityAnalysis: modelType '${modelType}' not in WASM kernel. ` +
        `Supported: ['tna', 'ftna']. Use tnaj.reliabilityAnalysis for atna / ctna.`,
    );
  }
  if (sequenceData.length < 4) {
    throw new Error('Need at least 4 sequences for reliability analysis');
  }

  const {
    iter = 100,
    split = 0.5,
    seed = 42,
    scaling,
    addStartState,
    startStateLabel,
    addEndState,
    endStateLabel,
  } = opts;

  // Mirror tnaj's start/end-state insertion (per-sequence head/tail trim + sentinel).
  let prepared: SequenceData = sequenceData;
  if (addStartState || addEndState) {
    prepared = sequenceData.map((seq) => {
      let last = seq.length - 1;
      while (last >= 0 && seq[last] === null) last--;
      const trimmed: (string | null)[] = seq.slice(0, last + 1);
      if (addStartState) trimmed.unshift(startStateLabel || 'Start');
      if (addEndState) trimmed.push(endStateLabel || 'End');
      return trimmed;
    }) as SequenceData;
  }

  // Build full label inventory.
  const labelSet = new Set<string>();
  for (const seq of prepared) for (const v of seq) if (v != null) labelSet.add(v);
  const labels = [...labelSet].sort();
  const ig = integerize(
    prepared as unknown as readonly (readonly (string | null)[])[],
    labels,
  );

  const r = reliabilityAnalysisWasm({
    values: ig.values,
    rowStarts: ig.rowStarts,
    nStates: labels.length,
    type: modelType === 'tna' ? 'relative' : 'frequency',
    scaling: scaling ? [scaling as 'minmax' | 'max' | 'rank'] : [],
    iter,
    split,
    seed,
  });

  // iter × 22 matrix → Record<metricKey, number[]>
  const iterations: Record<string, number[]> = {};
  for (let m = 0; m < RELIABILITY_METRIC_KEYS.length; m++) {
    const key = RELIABILITY_METRIC_KEYS[m]!;
    iterations[key] = r.iterations.map((row) => row[m]!);
  }

  const summary = RELIABILITY_METRICS.map((metDef, idx) => {
    const s = r.summary[idx]!;
    return {
      metric: metDef.label,
      category: metDef.category,
      mean: s.mean,
      sd: s.sd,
      median: s.median,
      min: s.min,
      max: s.max,
      q25: s.q25,
      q75: s.q75,
    };
  });

  return {
    iterations,
    summary,
    iter,
    split,
    modelType,
  };
}
