/**
 * compareWeightMatrices — WASM-backed. 22 reliability metrics on two
 * weight matrices. Same Record<string, number> shape as tnaj.
 *
 * reliabilityAnalysis (split-half pipeline) is not yet WASM-ported — it
 * iteratively splits sequences, builds models, and calls
 * compareWeightMatrices per iteration. The inner loop is JS but the
 * per-call comparison goes through the WASM kernel here.
 */
import { compareWeightMatricesWasm, RELIABILITY_METRIC_KEYS } from '../wasm-engine/index-pure.js';
import type { TNA } from '../index.js';
import { assertReady } from './assert.js';
import { flattenWeights } from './model.js';

export function compareWeightMatrices(a: TNA, b: TNA): Record<string, number> {
  assertReady();
  // Match tnaj: NaN-fill on mismatched label sets.
  if (a.labels.length !== b.labels.length || a.labels.length === 0) {
    const out: Record<string, number> = {};
    for (const k of RELIABILITY_METRIC_KEYS) out[k] = NaN;
    return out;
  }
  const matA = flattenWeights(a);
  const matB = flattenWeights(b);
  return compareWeightMatricesWasm({ matA, matB, nStates: a.labels.length }) as Record<string, number>;
}

export { RELIABILITY_METRIC_KEYS };
