/**
 * centralities — WASM-backed. Hard engine: any measure outside the WASM
 * set throws. Use `tnaj.centralities` for unsupported measures (e.g.
 * EigenvectorCentrality) or for GroupTNA models.
 */
import { centralitiesWasm, type CentralityMeasureFullName } from '../wasm-engine/index-pure.js';
import type { CentralityMeasure, CentralityResult, TNA } from '../index.js';
import { assertReady } from './assert.js';
import { flattenWeights } from './model.js';

const WASM_MEASURES: ReadonlySet<CentralityMeasureFullName> = new Set([
  'OutStrength', 'InStrength', 'Betweenness',
  'PageRank', 'Diffusion',
  'ClosenessIn', 'ClosenessOut', 'Closeness',
  'Clustering', 'BetweennessRSP',
]);

export function centralities(
  model: TNA,
  options: { loops?: boolean; normalize?: boolean; measures?: CentralityMeasure[] } = {},
): CentralityResult {
  assertReady();
  if ((model as { __group?: unknown }).__group) {
    throw new Error('tnaw.centralities: GroupTNA not supported. Use tnaj.centralities for grouped models.');
  }
  const { loops = false, normalize = false } = options;
  const requested: CentralityMeasure[] =
    options.measures ?? (['OutStrength', 'InStrength', 'Betweenness'] as CentralityMeasure[]);

  const unsupported = requested.filter((m) => !WASM_MEASURES.has(m as CentralityMeasureFullName));
  if (unsupported.length > 0) {
    throw new Error(
      `tnaw.centralities: measure(s) [${unsupported.join(', ')}] not in WASM kernel. ` +
        `Supported: [${[...WASM_MEASURES].join(', ')}]. Use tnaj.centralities for unsupported measures.`,
    );
  }

  const W = flattenWeights(model);
  const r = centralitiesWasm({
    weights: W,
    nStates: model.labels.length,
    measures: requested as CentralityMeasureFullName[],
    loops,
    normalize,
  });
  const measuresOut: Record<string, Float64Array> = {};
  for (const k of requested) measuresOut[k] = new Float64Array(r[k as CentralityMeasureFullName]);
  return {
    labels: [...model.labels],
    measures: measuresOut as CentralityResult['measures'],
  };
}
