/**
 * WASMengine TS shim — PLAN.md §3 architecture diagram.
 *
 * Public surface of the Phase A harness:
 *   initWasmEngine(opts?)
 *   bootstrapInnerWasm(...)  — one call per analysis (§4 boundary)
 *
 * Phase A is consumed only by `tests/` and `benchmarks/` inside WASMengine,
 * NEVER by the `tnaj` package surface (§2 isolation contract). Phase B will
 * add a one-line `tnaj`-public `initWasm()` wrapper.
 *
 * §8 ABI contract: every Float64Array returned to callers is freshly
 * allocated, never a view into WASM linear memory.
 */

// Note: getExports/isInitialized come from load-shared so this module does
// NOT transitively pull in the node-only `load.ts` (with `import('../pkg/…')`)
// into browser bundles. Callers pick `initWasmEngine` from load.ts (node)
// or `initWasmEngineWeb` from load-web.ts (browser) explicitly.
import { getExports, isInitialized } from './load-shared.js';
export { isInitialized };
export type { InitWasmOptions } from './load.js';

export type BootstrapMethod = 'stability' | 'threshold';

export interface BootstrapInnerInput {
  /** Number of states (square matrix dimension). */
  a: number;
  /** Number of sequences. */
  n: number;
  /** Per-sequence weight contributions, flat row-major length `n * a * a`. */
  perSeqWeights: Float64Array;
  /** Per-sequence row totals, flat length `n * a`. */
  perSeqRowTotals: Float64Array;
  /** Aggregated original weights, flat length `a * a`. */
  originalWeights: Float64Array;
  /** Bootstrap iterations. */
  iter: number;
  /** u32 seed passed to SeededRNG. */
  seed: number;
  /** Method ('stability' or 'threshold'). */
  method: BootstrapMethod;
  /** Confidence level (e.g. 0.05 for 95% CI). */
  level: number;
  /** Stability consistency range lower (e.g. 0.75). Ignored if method='threshold'. */
  consistencyLo: number;
  /** Stability consistency range upper (e.g. 1.25). Ignored if method='threshold'. */
  consistencyHi: number;
  /** Threshold (used when method='threshold'). */
  threshold: number;
}

export interface BootstrapInnerResult {
  /** All length `a * a`, row-major. Allocated on the JS heap. */
  weightsMean: Float64Array;
  weightsSd: Float64Array;
  weightsBias: Float64Array;
  pValues: Float64Array;
  ciLower: Float64Array;
  ciUpper: Float64Array;
}

export type TransitionType = 'relative' | 'frequency';
export type ScalingName = 'minmax' | 'max' | 'rank';

export interface BootstrapTnaInput {
  /** Integerized sequences, flat. Use the `integerize()` helper to build. */
  values: Int32Array;
  /** Length n+1: rowStarts[i]..rowStarts[i+1] gives row i's slice. */
  rowStarts: Uint32Array;
  /** Number of states (== labels.length on the JS side). */
  nStates: number;
  /** 'relative' (TNA, row-normalized) or 'frequency' (FTNA, raw counts). */
  type: TransitionType;
  /** Ordered scaling pipeline applied to the aggregated weights. Empty = none. */
  scaling: readonly ScalingName[];
  /** Bootstrap iterations. */
  iter: number;
  /** u32 seed for SeededRNG. */
  seed: number;
  /** 'stability' (consistency-range) or 'threshold' (below-threshold count). */
  method: BootstrapMethod;
  /** Confidence level (e.g. 0.05 for 95% CI). */
  level: number;
  /** Stability lower (e.g. 0.75). Ignored if method='threshold'. */
  consistencyLo: number;
  /** Stability upper (e.g. 1.25). Ignored if method='threshold'. */
  consistencyHi: number;
  /** Threshold value; pass `null` to use the 10th-percentile default. */
  threshold: number | null;
}

export interface BootstrapTnaResult {
  /** Pre-resampling original weight matrix, post row-norm + scaling. */
  originalWeights: Float64Array;
  weightsMean: Float64Array;
  weightsSd: Float64Array;
  weightsBias: Float64Array;
  pValues: Float64Array;
  ciLower: Float64Array;
  ciUpper: Float64Array;
  inits: Float64Array;
  /** Resolved threshold (the input or the 10th-percentile default). */
  thresholdUsed: number;
}

/**
 * Full bootstrap_tna kernel call. Equivalent to TS `bootstrapTna(model, opts)`
 * but takes integerized sequences directly — no `TNA` model object.
 *
 * §8 ABI: the flat result is sliced into seven a*a blocks + an inits block +
 * a scalar threshold, each in a freshly-allocated JS-heap typed array.
 */
export function bootstrapTnaWasm(input: BootstrapTnaInput): BootstrapTnaResult {
  const exports = getExports();
  const a = input.nStates;
  const aa = a * a;
  const expectedRowStartsLen = (input.rowStarts.length - 1) >= 0 ? input.rowStarts.length : 1;
  if (expectedRowStartsLen < 2) {
    throw new Error('rowStarts must have at least 2 entries (one sequence)');
  }
  const typeCode = input.type === 'relative' ? 0 : 1;
  const methodCode = input.method === 'stability' ? 0 : 1;
  const scalingCsv = input.scaling.join(',');
  const thresholdEncoded = input.threshold === null ? -1.0 : input.threshold;
  const flat = exports.bootstrap_tna_wasm(
    input.values,
    input.rowStarts,
    a,
    typeCode,
    scalingCsv,
    input.iter,
    input.seed,
    methodCode,
    input.level,
    input.consistencyLo,
    input.consistencyHi,
    thresholdEncoded,
  );
  // Result layout: 7 × a*a + a (inits) + 1 (threshold_used)
  return {
    originalWeights: flat.slice(0 * aa, 1 * aa),
    weightsMean: flat.slice(1 * aa, 2 * aa),
    weightsSd: flat.slice(2 * aa, 3 * aa),
    weightsBias: flat.slice(3 * aa, 4 * aa),
    pValues: flat.slice(4 * aa, 5 * aa),
    ciLower: flat.slice(5 * aa, 6 * aa),
    ciUpper: flat.slice(6 * aa, 7 * aa),
    inits: flat.slice(7 * aa, 7 * aa + a),
    thresholdUsed: flat[7 * aa + a]!,
  };
}

export type PAdjustName = 'none' | 'bonferroni' | 'holm' | 'BH' | 'fdr';

/** 22 reliability metric keys, in the order returned by `compareWeightMatricesWasm`. */
export const RELIABILITY_METRIC_KEYS = [
  'mad', 'median_ad', 'rmsd', 'max_ad', 'rel_mad', 'cv_ratio',
  'pearson', 'spearman', 'kendall', 'dcor',
  'euclidean', 'manhattan', 'canberra', 'braycurtis', 'frobenius',
  'cosine', 'jaccard', 'dice', 'overlap', 'rv',
  'rank_agree', 'sign_agree',
] as const;
export type ReliabilityMetricKey = (typeof RELIABILITY_METRIC_KEYS)[number];

export interface ReliabilityCompareInput {
  /** Flat row-major n×n weight matrix. */
  matA: Float64Array;
  /** Flat row-major n×n weight matrix. */
  matB: Float64Array;
  nStates: number;
}

export type ReliabilityCompareResult = Record<ReliabilityMetricKey, number>;

export type CentralityMeasureName = 'OutStrength' | 'InStrength' | 'Betweenness';
export type CorrelationMethod = 'pearson' | 'spearman' | 'kendall';

export interface EstimateCsInput {
  values: Int32Array;
  rowStarts: Uint32Array;
  nStates: number;
  type: TransitionType;
  scaling: readonly ScalingName[];
  /** Subset of OutStrength | InStrength | Betweenness (Phase A.6.5 scope). */
  measures: readonly CentralityMeasureName[];
  iter: number;
  /** Drop proportions to test (e.g. [0.1, 0.2, ..., 0.7]). */
  dropProps: readonly number[];
  /** Correlation threshold for `propAbove` calculation. */
  threshold: number;
  /** Certainty cutoff for CS coefficient (e.g. 0.95). */
  certainty: number;
  seed: number;
  corrMethod: CorrelationMethod;
  loops: boolean;
}

export interface EstimateCsResult {
  /** CS coefficient per measure (same order as input.measures). */
  csCoefficients: number[];
  /** Mean correlations per measure × dropProp. measureIdx × dropPropIdx layout. */
  meanCorrelations: number[][];
  /**
   * Raw correlations per measure: iter × nDropProp matrix. NaN where the
   * dropped sample produced a degenerate centrality vector.
   */
  correlations: number[][][];
  /** Summary rows per (measure, dropProp). */
  summary: Array<{
    measure: CentralityMeasureName;
    dropProp: number;
    meanCor: number;
    sdCor: number;
    propAbove: number;
  }>;
}

/**
 * Centrality stability estimate via case-dropping bootstrap.
 * Phase A.6.5: only OutStrength, InStrength, Betweenness measures supported.
 *
 * §8 ABI: result is copied out into fresh JS-heap arrays.
 */
export function estimateCsWasm(input: EstimateCsInput): EstimateCsResult {
  const exports = getExports();
  const nM = input.measures.length;
  const nDp = input.dropProps.length;
  const dropPropsF = new Float64Array(input.dropProps);
  const flat = exports.estimate_cs_wasm(
    input.values,
    input.rowStarts,
    input.nStates,
    input.type === 'relative' ? 0 : 1,
    input.scaling.join(','),
    input.measures.join(','),
    input.iter,
    dropPropsF,
    input.threshold,
    input.certainty,
    input.seed,
    input.corrMethod,
    input.loops ? 1 : 0,
  );
  // Layout:
  //   cs[nM]
  //   meanCorr[nM*nDp]            (measure-major)
  //   correlations[nM*iter*nDp]   (measure → iter → dropProp)
  //   sumMean[nM*nDp] | sumSd[nM*nDp] | sumPropAbove[nM*nDp]
  const iter = input.iter;
  const csCoefficients = Array.from(flat.slice(0, nM));
  const meanCorrelations: number[][] = [];
  for (let m = 0; m < nM; m++) {
    const start = nM + m * nDp;
    meanCorrelations.push(Array.from(flat.slice(start, start + nDp)));
  }
  const corrBase = nM + nM * nDp;
  const correlations: number[][][] = [];
  for (let m = 0; m < nM; m++) {
    const measureBase = corrBase + m * iter * nDp;
    const matrix: number[][] = [];
    for (let it = 0; it < iter; it++) {
      const rowStart = measureBase + it * nDp;
      matrix.push(Array.from(flat.slice(rowStart, rowStart + nDp)));
    }
    correlations.push(matrix);
  }
  const sumMeanOff = corrBase + nM * iter * nDp;
  const sumSdOff = sumMeanOff + nM * nDp;
  const sumPaOff = sumSdOff + nM * nDp;
  const summary: EstimateCsResult['summary'] = [];
  for (let m = 0; m < nM; m++) {
    for (let j = 0; j < nDp; j++) {
      summary.push({
        measure: input.measures[m]!,
        dropProp: input.dropProps[j]!,
        meanCor: flat[sumMeanOff + m * nDp + j]!,
        sdCor: flat[sumSdOff + m * nDp + j]!,
        propAbove: flat[sumPaOff + m * nDp + j]!,
      });
    }
  }
  return { csCoefficients, meanCorrelations, correlations, summary };
}

export interface MarkovOrderTestInput {
  /** Integerized trajectories: flat values, NA = -1. */
  values: Int32Array;
  rowStarts: Uint32Array;
  /** Maximum order to test (≥1). Capped at `longest_sequence - 1` internally. */
  maxOrder: number;
  /** Number of within-w permutations (≥1). */
  nPerm: number;
  /** Significance level for the sequential rejection test (0 < α < 1). */
  alpha: number;
  /** Seed for the RNG. */
  seed: number;
}

export interface MarkovOrderTestResult {
  /** Per-order panel rows: index 0..=maxOrder. */
  testTable: Array<{
    order: number;
    loglik: number;
    aic: number;
    bic: number;
    df: number; // NaN for order 0
    g2: number; // NaN for order 0
    pPermutation: number; // NaN for order 0
    pAsymptotic: number; // NaN for order 0
    significant: boolean; // false for order 0
  }>;
  /**
   * Per-order empirical null G² distribution. `permutationNull[k-1]` is a
   * `number[]` of length ≤ nPerm (orders whose df=0 yield empty arrays).
   * Length is `maxOrder`, since order 0 has no permutation test.
   */
  permutationNull: number[][];
  /**
   * Fitted transition matrices, one per order 0..=maxOrder.
   *   index 0: marginal row-vector of length nStates (conceptually 1×nStates).
   *   index k ≥ 1: row-major n_k × n_k matrix (n_k = transitionNodes[k].length).
   * Stored as flat `Float64Array` for cheap WASM marshaling; consumers in
   * tnajw repack into tnaj's `Matrix` class.
   */
  transitionMatrices: Float64Array[];
  /**
   * Node tuples per order (as state indices). transitionNodes[k][i] is a
   * length-k tuple (or length-1 for k=0). Map indices back to label names
   * using the integerization label list to get a `string[][]`.
   */
  transitionNodes: number[][][];
  /** Total number of input sequences that survived NA trimming. */
  nSequences: number;
  /** Total number of observations across all sequences. */
  nObservations: number;
  /** Per-order tuple count (length maxOrder; orders 1..=K). */
  nTuples: number[];
  optimalOrder: number;
  bicOrder: number;
  aicOrder: number;
}

/**
 * Markov order test (Nestimate parity). Returns the per-order panel, the
 * empirical permutation-null G² distribution per order, and the
 * sequential / BIC / AIC optimal orders. Significant-flags and fitted
 * transition matrices are not exposed — call the Rust kernel directly via
 * cargo if you need them.
 */
export function markovOrderTestWasm(input: MarkovOrderTestInput): MarkovOrderTestResult {
  const exports = getExports();
  const k1 = input.maxOrder + 1;
  const flat = exports.markov_order_test_wasm(
    input.values,
    input.rowStarts,
    input.maxOrder,
    input.nPerm,
    input.alpha,
    input.seed,
  );
  const testTable: MarkovOrderTestResult['testTable'] = [];
  for (let k = 0; k < k1; k++) {
    testTable.push({
      order: k,
      loglik: flat[0 * k1 + k]!,
      aic: flat[1 * k1 + k]!,
      bic: flat[2 * k1 + k]!,
      df: flat[3 * k1 + k]!,
      g2: flat[4 * k1 + k]!,
      pPermutation: flat[5 * k1 + k]!,
      pAsymptotic: flat[6 * k1 + k]!,
      significant: false, // populated below once we know the trailing offset
    });
  }
  // permutationNull lives at offset 7*k1 + 3, as maxOrder × nPerm row-major.
  // NaN entries indicate the order had df=0 (empty kernel-side vec).
  const permBase = 7 * k1 + 3;
  const permutationNull: number[][] = [];
  for (let order = 1; order <= input.maxOrder; order++) {
    const rowStart = permBase + (order - 1) * input.nPerm;
    const row: number[] = [];
    for (let p = 0; p < input.nPerm; p++) {
      const v = flat[rowStart + p]!;
      if (!Number.isNaN(v)) row.push(v);
    }
    permutationNull.push(row);
  }
  // Fitted-models block follows the permutation null.
  let cursor = permBase + input.maxOrder * input.nPerm;
  const nodesPerOrder: number[] = [];
  for (let k = 0; k < k1; k++) {
    nodesPerOrder.push(flat[cursor + k]!);
  }
  cursor += k1;
  const transitionMatrices: Float64Array[] = [];
  for (let k = 0; k < k1; k++) {
    const nk = nodesPerOrder[k]!;
    const size = k === 0 ? nk : nk * nk;
    const buf = new Float64Array(size);
    for (let i = 0; i < size; i++) buf[i] = flat[cursor + i]!;
    transitionMatrices.push(buf);
    cursor += size;
  }
  const transitionNodes: number[][][] = [];
  for (let k = 0; k < k1; k++) {
    const nk = nodesPerOrder[k]!;
    const tupleLen = k === 0 ? 1 : k;
    const nodes: number[][] = [];
    for (let i = 0; i < nk; i++) {
      const tup: number[] = [];
      for (let j = 0; j < tupleLen; j++) {
        tup.push(flat[cursor + i * tupleLen + j]!);
      }
      nodes.push(tup);
    }
    transitionNodes.push(nodes);
    cursor += nk * tupleLen;
  }
  // Trailing summary block:
  //   n_sequences, n_observations, n_tuples[K], significant[K+1]
  const nSequences = flat[cursor]!;
  const nObservations = flat[cursor + 1]!;
  cursor += 2;
  const nTuples: number[] = [];
  for (let k = 0; k < input.maxOrder; k++) {
    nTuples.push(flat[cursor + k]!);
  }
  cursor += input.maxOrder;
  for (let k = 0; k < k1; k++) {
    testTable[k]!.significant = flat[cursor + k] === 1;
  }
  return {
    testTable,
    permutationNull,
    transitionMatrices,
    transitionNodes,
    nSequences,
    nObservations,
    nTuples,
    optimalOrder: flat[7 * k1]!,
    bicOrder: flat[7 * k1 + 1]!,
    aicOrder: flat[7 * k1 + 2]!,
  };
}

/**
 * Compare two weight matrices via the 22 reliability metrics in the Rust kernel.
 * §8 ABI: result is copied out into a fresh `Record<>`.
 */
export function compareWeightMatricesWasm(input: ReliabilityCompareInput): ReliabilityCompareResult {
  const exports = getExports();
  if (input.matA.length !== input.nStates * input.nStates) {
    throw new Error(`matA length ${input.matA.length} != n*n = ${input.nStates * input.nStates}`);
  }
  if (input.matB.length !== input.nStates * input.nStates) {
    throw new Error(`matB length ${input.matB.length} != n*n = ${input.nStates * input.nStates}`);
  }
  const flat = exports.compare_weight_matrices_wasm(input.matA, input.matB, input.nStates);
  const out = {} as ReliabilityCompareResult;
  for (let i = 0; i < RELIABILITY_METRIC_KEYS.length; i++) {
    out[RELIABILITY_METRIC_KEYS[i]!] = flat[i]!;
  }
  return out;
}

export interface PermutationTestInput {
  valuesX: Int32Array;
  rowStartsX: Uint32Array;
  valuesY: Int32Array;
  rowStartsY: Uint32Array;
  nStates: number;
  type: TransitionType;
  scaling: readonly ScalingName[];
  iter: number;
  seed: number;
  /** P-value adjustment method ('none', 'bonferroni', 'holm', 'BH', 'fdr'). */
  adjust: PAdjustName;
  level: number;
  /** Paired test (requires nX === nY). */
  paired: boolean;
}

export interface PermutationTestResult {
  originalWeightsX: Float64Array;
  originalWeightsY: Float64Array;
  diffTrue: Float64Array;
  diffSig: Float64Array;
  pValues: Float64Array;
  effectSizes: Float64Array;
}

/**
 * Permutation test kernel. Equivalent to TS `permutationTest(x, y, opts)`.
 *
 * §8 ABI: result is copied out into 6 fresh JS-heap typed arrays.
 */
export function permutationTestWasm(input: PermutationTestInput): PermutationTestResult {
  const exports = getExports();
  const a = input.nStates;
  const aa = a * a;
  const typeCode = input.type === 'relative' ? 0 : 1;
  const scalingCsv = input.scaling.join(',');
  const flat = exports.permutation_test_wasm(
    input.valuesX,
    input.rowStartsX,
    input.valuesY,
    input.rowStartsY,
    a,
    typeCode,
    scalingCsv,
    input.iter,
    input.seed,
    input.adjust,
    input.level,
    input.paired ? 1 : 0,
  );
  return {
    originalWeightsX: flat.slice(0 * aa, 1 * aa),
    originalWeightsY: flat.slice(1 * aa, 2 * aa),
    diffTrue: flat.slice(2 * aa, 3 * aa),
    diffSig: flat.slice(3 * aa, 4 * aa),
    pValues: flat.slice(4 * aa, 5 * aa),
    effectSizes: flat.slice(5 * aa, 6 * aa),
  };
}

/**
 * One bootstrap inner-loop kernel call. The Rust side runs the full
 * resampling loop in `iter` iterations and aggregates per-edge stats.
 *
 * §8 ABI: the WASM-returned `Float64Array` (a view into linear memory) is
 * sliced into six independent JS-heap-allocated copies before this function
 * returns. Caller-side references remain valid even after another WASM call
 * grows or repurposes the underlying memory.
 */
export function bootstrapInnerWasm(input: BootstrapInnerInput): BootstrapInnerResult {
  const exports = getExports();
  const aa = input.a * input.a;
  if (input.perSeqWeights.length !== input.n * aa) {
    throw new Error(`perSeqWeights length ${input.perSeqWeights.length} != n*a*a = ${input.n * aa}`);
  }
  if (input.perSeqRowTotals.length !== input.n * input.a) {
    throw new Error(`perSeqRowTotals length ${input.perSeqRowTotals.length} != n*a = ${input.n * input.a}`);
  }
  if (input.originalWeights.length !== aa) {
    throw new Error(`originalWeights length ${input.originalWeights.length} != a*a = ${aa}`);
  }
  const methodCode = input.method === 'stability' ? 0 : 1;
  const flat = exports.bootstrap_inner_wasm(
    input.a,
    input.n,
    input.perSeqWeights,
    input.perSeqRowTotals,
    input.originalWeights,
    input.iter,
    input.seed,
    methodCode,
    input.level,
    input.consistencyLo,
    input.consistencyHi,
    input.threshold,
  );
  // §8: copy out, never alias. `slice()` allocates a fresh JS-heap buffer.
  return {
    weightsMean: flat.slice(0 * aa, 1 * aa),
    weightsSd: flat.slice(1 * aa, 2 * aa),
    weightsBias: flat.slice(2 * aa, 3 * aa),
    pValues: flat.slice(3 * aa, 4 * aa),
    ciLower: flat.slice(4 * aa, 5 * aa),
    ciUpper: flat.slice(5 * aa, 6 * aa),
  };
}

