// Phase A.7+ — 11 new kernel wrappers (centralities, passage_time,
// markov_stability, honem, path_dependence, mogen, hypa, hon, pathways).
//
// Fixed-shape kernels return typed arrays sliced from a flat block.
// Variable-shape kernels return JSON strings parsed once per call.
// ────────────────────────────────────────────────────────────────────────

/** All 10 centrality measures the Rust kernel can compute. */
export type CentralityMeasureFullName =
  | 'OutStrength' | 'InStrength' | 'Betweenness'
  | 'PageRank' | 'Diffusion'
  | 'ClosenessIn' | 'ClosenessOut' | 'Closeness'
  | 'Clustering' | 'BetweennessRSP';

export interface CentralitiesInput {
  /** Flat row-major n×n weight matrix. */
  weights: Float64Array;
  nStates: number;
  measures: readonly CentralityMeasureFullName[];
  /** If false, diagonal is zeroed before computation. */
  loops: boolean;
  /** Per-measure min-max normalize. */
  normalize: boolean;
}

export type CentralitiesResult = Record<CentralityMeasureFullName, number[]>;

/**
 * Compute centralities directly (no case-dropping, no RNG). Returns a record
 * keyed by measure name; each value is an `n_states`-long array.
 */
export function centralitiesWasm(input: CentralitiesInput): CentralitiesResult {
  const exports = getExports();
  if (input.weights.length !== input.nStates * input.nStates) {
    throw new Error(`weights length ${input.weights.length} != n*n = ${input.nStates * input.nStates}`);
  }
  const flat = exports.centralities_wasm(
    input.weights,
    input.nStates,
    input.measures.join(','),
    input.loops ? 1 : 0,
    input.normalize ? 1 : 0,
  );
  const out: Partial<CentralitiesResult> = {};
  for (let m = 0; m < input.measures.length; m++) {
    out[input.measures[m]!] = Array.from(flat.slice(m * input.nStates, (m + 1) * input.nStates));
  }
  return out as CentralitiesResult;
}

export interface PassageTimeInput {
  /** Flat row-major n×n stochastic-ish matrix. */
  p: Float64Array;
  nStates: number;
  /** Row-normalise rows that don't sum to 1 (default true). */
  normalize?: boolean;
}

export interface PassageTimeResult {
  /** n×n MFPT matrix, flat row-major. */
  mfpt: Float64Array;
  /** Stationary distribution π, length n. */
  stationary: Float64Array;
  /** Self-loop probabilities P[i,i] (post-normalisation). */
  persistence: Float64Array;
}

export function passageTimeWasm(input: PassageTimeInput): PassageTimeResult {
  const exports = getExports();
  const n = input.nStates;
  if (input.p.length !== n * n) {
    throw new Error(`p length ${input.p.length} != n*n = ${n * n}`);
  }
  const flat = exports.passage_time_wasm(input.p, n, input.normalize === false ? 0 : 1);
  return {
    mfpt: flat.slice(0, n * n),
    stationary: flat.slice(n * n, n * n + n),
    persistence: flat.slice(n * n + n, n * n + 2 * n),
  };
}

export interface MarkovStabilityRow {
  persistence: number;
  stationaryProb: number;
  returnTime: number;
  sojournTime: number;
  avgTimeToOthers: number;
  avgTimeFromOthers: number;
}

export interface MarkovStabilityResult {
  rows: MarkovStabilityRow[];
  mfpt: Float64Array;
  stationary: Float64Array;
  persistence: Float64Array;
}

export function markovStabilityWasm(input: PassageTimeInput): MarkovStabilityResult {
  const exports = getExports();
  const n = input.nStates;
  if (input.p.length !== n * n) {
    throw new Error(`p length ${input.p.length} != n*n = ${n * n}`);
  }
  const flat = exports.markov_stability_wasm(input.p, n, input.normalize === false ? 0 : 1);
  // 6n metrics in measure-major order
  const rows: MarkovStabilityRow[] = [];
  for (let i = 0; i < n; i++) {
    rows.push({
      persistence: flat[0 * n + i]!,
      stationaryProb: flat[1 * n + i]!,
      returnTime: flat[2 * n + i]!,
      sojournTime: flat[3 * n + i]!,
      avgTimeToOthers: flat[4 * n + i]!,
      avgTimeFromOthers: flat[5 * n + i]!,
    });
  }
  const tailOff = 6 * n;
  return {
    rows,
    mfpt: flat.slice(tailOff, tailOff + n * n),
    stationary: flat.slice(tailOff + n * n, tailOff + n * n + n),
    persistence: flat.slice(tailOff + n * n + n, tailOff + n * n + 2 * n),
  };
}

export interface HonemInput {
  /** Flat row-major n×n HON adjacency matrix. */
  adj: Float64Array;
  nNodes: number;
  /** Requested embedding dimension. */
  dim: number;
  /** Maximum random-walk power (default 5). */
  maxPower: number;
}

export interface HonemResult {
  /** Flat row-major n × dim embedding matrix. */
  embeddings: Float64Array;
  singularValues: Float64Array;
  explainedVariance: number;
  /** Actual dim returned (may be < dim if rank-deficient). */
  dim: number;
}

export function honemWasm(input: HonemInput): HonemResult {
  const exports = getExports();
  const n = input.nNodes;
  if (input.adj.length !== n * n) {
    throw new Error(`adj length ${input.adj.length} != n*n = ${n * n}`);
  }
  const flat = exports.honem_wasm(input.adj, n, input.dim, input.maxPower);
  const actualDim = flat[flat.length - 1]!;
  const dim = actualDim | 0;
  return {
    embeddings: flat.slice(0, n * dim),
    singularValues: flat.slice(n * dim, n * dim + dim),
    explainedVariance: flat[n * dim + dim]!,
    dim,
  };
}

