export type CasedropCorrMethod = 'pearson' | 'spearman' | 'kendall';

export interface CasedropReliabilityInput {
  values: Int32Array;
  rowStarts: Uint32Array;
  nStates: number;
  type: TransitionType;
  scaling: readonly ScalingName[];
  iter: number;
  dropProps: readonly number[];
  threshold: number;
  certainty: number;
  method: CasedropCorrMethod;
  includeDiag: boolean;
  seed: number;
}

export interface CasedropMetricSummaryRow {
  metric: 'mean_abs_dev' | 'median_abs_dev' | 'correlation' | 'max_abs_dev';
  dropProp: number;
  mean: number;
  sd: number;
  median: number;
  mad: number;
  q025: number;
  q975: number;
}

export interface CasedropReliabilityResultWasm {
  cs: number;
  /** Per-metric (nProp × iter) matrices, row-major. */
  meanAbsDev: number[][];
  medianAbsDev: number[][];
  correlation: number[][];
  maxAbsDev: number[][];
  summary: CasedropMetricSummaryRow[];
  nEdges: number;
  nCases: number;
}

const METRIC_NAMES: CasedropMetricSummaryRow['metric'][] = [
  'mean_abs_dev', 'median_abs_dev', 'correlation', 'max_abs_dev',
];

export function casedropReliabilityWasm(input: CasedropReliabilityInput): CasedropReliabilityResultWasm {
  const exports = getExports();
  const nProp = input.dropProps.length;
  const iter = input.iter;
  const a = nProp * iter;
  const flat = exports.casedrop_reliability_wasm(
    input.values,
    input.rowStarts,
    input.nStates,
    input.type === 'relative' ? 0 : 1,
    input.scaling.join(','),
    iter,
    new Float64Array(input.dropProps),
    input.threshold,
    input.certainty,
    input.method,
    input.includeDiag ? 1 : 0,
    input.seed,
  );
  const sliceMat = (off: number): number[][] => {
    const out: number[][] = [];
    for (let p = 0; p < nProp; p++) {
      const row: number[] = [];
      for (let it = 0; it < iter; it++) row.push(flat[off + p * iter + it]!);
      out.push(row);
    }
    return out;
  };
  const meanAbsDev = sliceMat(0);
  const medianAbsDev = sliceMat(a);
  const correlation = sliceMat(2 * a);
  const maxAbsDev = sliceMat(3 * a);

  const summary: CasedropMetricSummaryRow[] = [];
  let off = 4 * a;
  for (const m of METRIC_NAMES) {
    for (let p = 0; p < nProp; p++) {
      summary.push({
        metric: m,
        dropProp: input.dropProps[p]!,
        mean: flat[off++]!,
        sd: flat[off++]!,
        median: flat[off++]!,
        mad: flat[off++]!,
        q025: flat[off++]!,
        q975: flat[off++]!,
      });
    }
  }
  const cs = flat[off++]!;
  const nEdges = flat[off++]!;
  const nCases = flat[off]!;

  return { cs, meanAbsDev, medianAbsDev, correlation, maxAbsDev, summary, nEdges, nCases };
}

export interface ReliabilityAnalysisInput {
  values: Int32Array;
  rowStarts: Uint32Array;
  nStates: number;
  /** 'relative' for tna, 'frequency' for ftna. atna/ctna NOT supported in WASM. */
  type: TransitionType;
  scaling: readonly ScalingName[];
  iter: number;
  split: number;
  seed: number;
}

export interface ReliabilityMetricSummaryWasm {
  metricIdx: number;  // index into RELIABILITY_METRIC_KEYS
  mean: number;
  sd: number;
  median: number;
  min: number;
  max: number;
  q25: number;
  q75: number;
  nValid: number;
}

export interface ReliabilityAnalysisResultWasm {
  /** iter × 22 matrix of metrics, row-major. */
  iterations: number[][];
  summary: ReliabilityMetricSummaryWasm[];
  nSequences: number;
}

export function reliabilityAnalysisWasm(input: ReliabilityAnalysisInput): ReliabilityAnalysisResultWasm {
  const exports = getExports();
  const flat = exports.reliability_analysis_wasm(
    input.values,
    input.rowStarts,
    input.nStates,
    input.type === 'relative' ? 0 : 1,
    input.scaling.join(','),
    input.iter,
    input.split,
    input.seed,
  );
  const nM = 22;
  const iter = input.iter;
  const iterations: number[][] = [];
  for (let it = 0; it < iter; it++) {
    const row: number[] = [];
    for (let m = 0; m < nM; m++) row.push(flat[it * nM + m]!);
    iterations.push(row);
  }
  const summary: ReliabilityMetricSummaryWasm[] = [];
  let off = iter * nM;
  for (let m = 0; m < nM; m++) {
    summary.push({
      metricIdx: m,
      mean: flat[off++]!,
      sd: flat[off++]!,
      median: flat[off++]!,
      min: flat[off++]!,
      max: flat[off++]!,
      q25: flat[off++]!,
      q75: flat[off++]!,
      nValid: flat[off++]!,
    });
  }
  const nSequences = flat[off]!;
  return { iterations, summary, nSequences };
}

// ---- Clustering (cluster_string_wasm / cluster_numeric_wasm) ----

/** Linkage method codes — must match `kernels::cluster::Method::from_code`. */
export const CLUSTER_METHOD_CODES: Record<string, number> = {
  pam: 0,
  average: 1,
  complete: 2,
  single: 3,
  'ward.D': 4,
  'ward.D2': 5,
  mcquitty: 6,
  median: 7,
  centroid: 8,
};

/** String dissimilarity codes — must match `Dissimilarity::from_code`. */
export const CLUSTER_DISSIMILARITY_CODES: Record<string, number> = {
  hamming: 0,
  lv: 1,
  osa: 2,
  dl: 3,
  lcs: 4,
  qgram: 5,
  cosine: 6,
  jaccard: 7,
  jw: 8,
};

/** Numeric metric codes — must match `NumMetric::from_code`. */
export const CLUSTER_NUMERIC_METRIC_CODES: Record<string, number> = {
  euclidean: 0,
  manhattan: 1,
};

export interface ClusterStringWasmInput {
  /** Integerizer output: flat token ids, -1 = NA. */
  values: Int32Array;
  /** Integerizer output: length n+1 row offsets. */
  rowStarts: Uint32Array;
  /** Number of clusters (cut depth; 1 for dendrogram-only). */
  k: number;
  /** Linkage method name (key of CLUSTER_METHOD_CODES). */
  method: string;
  /** String dissimilarity name (key of CLUSTER_DISSIMILARITY_CODES). */
  dissimilarity: string;
  /** Hamming-only: exponential position weighting. */
  weighted: boolean;
  /** Hamming-only: decay rate when weighted. */
  lambda: number;
}

export interface ClusterNumericWasmInput {
  /** Row-major n × p matrix. */
  data: Float64Array;
  n: number;
  p: number;
  k: number;
  method: string;
  /** Numeric metric name (key of CLUSTER_NUMERIC_METRIC_CODES). */
  metric: string;
}

export interface ClusterWasmResult {
  n: number;
  k: number;
  silhouette: number;
  /** 1-indexed cluster label per observation, length n. */
  assignments: number[];
  /** Member count per cluster, length k. */
  sizes: number[];
  /** Flat row-major n*n distance matrix (freshly allocated, §8). */
  distance: Float64Array;
  /** hclust merge history (R convention). `undefined` for pam. */
  merge?: number[][];
  /** Merge heights. `undefined` for pam. */
  heights?: number[];
  /** 0-indexed dendrogram leaf order. `undefined` for pam. */
  order?: number[];
}

/** Decode the shared cluster flat-f64 ABI (see `encode_cluster`). */
function decodeCluster(flat: Float64Array): ClusterWasmResult {
  const n = flat[0]!;
  const k = flat[1]!;
  const silhouette = flat[2]!;
  const hasHier = flat[3]! === 1;
  let off = 4;
  const assignments: number[] = [];
  for (let i = 0; i < n; i++) assignments.push(flat[off++]!);
  const sizes: number[] = [];
  for (let i = 0; i < k; i++) sizes.push(flat[off++]!);
  const distance = new Float64Array(n * n);
  for (let i = 0; i < n * n; i++) distance[i] = flat[off++]!;
  const result: ClusterWasmResult = { n, k, silhouette, assignments, sizes, distance };
  if (hasHier) {
    const nm1 = Math.max(0, n - 1);
    const merge: number[][] = [];
    for (let s = 0; s < nm1; s++) {
      merge.push([flat[off]!, flat[off + 1]!]);
      off += 2;
    }
    const heights: number[] = [];
    for (let s = 0; s < nm1; s++) heights.push(flat[off++]!);
    const order: number[] = [];
    for (let i = 0; i < n; i++) order.push(flat[off++]!);
    result.merge = merge;
    result.heights = heights;
    result.order = order;
  }
  return result;
}

function clusterMethodCode(method: string): number {
  const c = CLUSTER_METHOD_CODES[method];
  if (c === undefined) throw new Error(`clusterWasm: unknown method "${method}"`);
  return c;
}

export function clusterStringWasm(input: ClusterStringWasmInput): ClusterWasmResult {
  const exports = getExports();
  const dCode = CLUSTER_DISSIMILARITY_CODES[input.dissimilarity];
  if (dCode === undefined) {
    throw new Error(`clusterStringWasm: unknown dissimilarity "${input.dissimilarity}"`);
  }
  const flat = exports.cluster_string_wasm(
    input.values,
    input.rowStarts,
    input.k,
    clusterMethodCode(input.method),
    dCode,
    input.weighted ? 1 : 0,
    input.lambda,
  );
  return decodeCluster(flat);
}

export interface ClusterFromDistWasmInput {
  /** Flat row-major n×n distance matrix. */
  dist: Float64Array;
  n: number;
  /** Cut depth (1 = dendrogram only). */
  k: number;
  /** Hierarchical method name (pam not valid here). */
  method: string;
}

export function clusterFromDistWasm(input: ClusterFromDistWasmInput): ClusterWasmResult {
  const exports = getExports();
  const flat = exports.cluster_from_dist_wasm(
    input.dist,
    input.n,
    input.k,
    clusterMethodCode(input.method),
  );
  return decodeCluster(flat);
}

export function clusterNumericWasm(input: ClusterNumericWasmInput): ClusterWasmResult {
  const exports = getExports();
  const mCode = CLUSTER_NUMERIC_METRIC_CODES[input.metric];
  if (mCode === undefined) {
    throw new Error(`clusterNumericWasm: unknown metric "${input.metric}"`);
  }
  const flat = exports.cluster_numeric_wasm(
    input.data,
    input.n,
    input.p,
    input.k,
    clusterMethodCode(input.method),
    mCode,
  );
  return decodeCluster(flat);
}


// ── MMM (mixture Markov model) — basic deterministic EM ────────────
//
// SEPARATE validation contract from the 1e-10-vs-R kernels (MMM-PLAN §0/§4):
// single-start EM, label-permutation identifiable, local optimum. The result
// is bit-reproducible for a fixed (input, seed, init); cross-checked against
// `Nestimate:::.mmm_em`, not stochastic seqHMM. WASM-only — no TS fallback.

export interface MmmWasmInput {
  /** Integerized sequences: flat values, NA = -1. Positions are NOT
   *  compacted — interior NA breaks a transition pair (Nestimate parity). */
  values: Int32Array;
  rowStarts: Uint32Array;
  /** Number of states S (≥2). */
  nStates: number;
  /** Number of mixture components K (≥2). */
  k: number;
  /** Max EM iterations (default 200). */
  maxIter?: number;
  /** Convergence tolerance on |Δloglik| (default 1e-8). */
  tol?: number;
  /** Laplace smoothing (R `smooth`; default 0.01). */
  alpha?: number;
  /** Seed for the xoshiro init (ignored when `initPosterior` is given). */
  seed?: number;
  /** Number of independent EM starts (default 1). Uses the deterministic
   *  seed sequence `seed..seed+nStarts-1` and keeps the highest-logLik
   *  fit; the whole multi-start result stays reproducible. Forced to 1
   *  when `initPosterior` is supplied. */
  nStarts?: number;
  /** Optional N×K row-major starting responsibilities. When provided it is
   *  consumed verbatim — this is how the R cross-check feeds a byte-identical
   *  starting point so 0-restart EM lands in the same basin. */
  initPosterior?: Float64Array;
}

export interface MmmWasmResult {
  n: number;
  k: number;
  /** Number of states S. */
  s: number;
  iterations: number;
  converged: boolean;
  logLik: number;
  aic: number;
  bic: number;
  /** Integrated Completed Likelihood = BIC + 2·classEntropy. */
  icl: number;
  /** Cluster-quality block — port of Nestimate `.mmm_quality`. */
  quality: {
    /** AvePP per cluster (length k). `NaN` for an empty cluster. */
    avepp: Float64Array;
    /** Overall AvePP = mean of per-sequence max posterior. */
    aveppOverall: number;
    /** Normalized entropy ∈ [0,1] (0 = perfect, 1 = random). */
    entropy: number;
    /** 1 − entropy. */
    relativeEntropy: number;
    /** Fraction of sequences with max posterior < 0.5. */
    classificationError: number;
    /** −Σ log(posterior[i, assignment_i] + ε). */
    classEntropy: number;
  };
  /** EM starts actually performed (1 if `initPosterior` was supplied). */
  nStarts: number;
  /** Per-restart converged logLik in seed order; `max` == `logLik`. A
   *  single distinct value ⇒ the extra starts found nothing new. */
  restartLogLiks: Float64Array;
  /** 1-indexed hard assignment per sequence (ties → lowest index). */
  assignments: number[];
  /** Posterior responsibilities, n rows × k. */
  responsibilities: number[][];
  /** Mixing weights, length k. */
  pi: Float64Array;
  /** Initial-state distribution per cluster (k arrays, each length s). */
  delta: Float64Array[];
  /** Transition matrix per cluster (k flat s×s row-major, row-stochastic). */
  transition: Float64Array[];
}

/**
 * MMM clustering (Nestimate `.mmm_em` parity, basic deterministic).
 * Linear in N — no N² distance matrix, so it scales where PAM/hierarchical
 * hit the n² wall (MMM-PLAN.md headline).
 */
export function mmmWasm(input: MmmWasmInput): MmmWasmResult {
  const exports = getExports();
  const {
    values,
    rowStarts,
    nStates,
    k,
    maxIter = 200,
    tol = 1e-8,
    alpha = 0.01,
    seed = 42,
    nStarts = 1,
    initPosterior,
  } = input;
  const flat = exports.mmm_wasm(
    values,
    rowStarts,
    nStates,
    k,
    maxIter,
    tol,
    alpha,
    seed,
    nStarts,
    initPosterior ?? new Float64Array(0),
  );
  const n = flat[0]!;
  const kk = flat[1]!;
  const s = flat[2]!;
  const iterations = flat[3]!;
  const converged = flat[4]! !== 0;
  const logLik = flat[5]!;
  const aic = flat[6]!;
  const bic = flat[7]!;
  const icl = flat[8]!;
  const aveppOverall = flat[9]!;
  const entropy = flat[10]!;
  const relativeEntropy = flat[11]!;
  const classificationError = flat[12]!;
  const classEntropy = flat[13]!;
  let off = 14;
  const assignments: number[] = [];
  for (let i = 0; i < n; i++) assignments.push(flat[off++]!);
  const responsibilities: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let m = 0; m < kk; m++) row.push(flat[off++]!);
    responsibilities.push(row);
  }
  const pi = new Float64Array(kk);
  for (let m = 0; m < kk; m++) pi[m] = flat[off++]!;
  const avepp = new Float64Array(kk);
  for (let m = 0; m < kk; m++) avepp[m] = flat[off++]!;
  const delta: Float64Array[] = [];
  for (let m = 0; m < kk; m++) {
    const d = new Float64Array(s);
    for (let st = 0; st < s; st++) d[st] = flat[off++]!;
    delta.push(d);
  }
  const transition: Float64Array[] = [];
  for (let m = 0; m < kk; m++) {
    const a = new Float64Array(s * s);
    for (let j = 0; j < s * s; j++) a[j] = flat[off++]!;
    transition.push(a);
  }
  const nStartsOut = flat[off++]!;
  const restartLogLiks = new Float64Array(nStartsOut);
  for (let r = 0; r < nStartsOut; r++) restartLogLiks[r] = flat[off++]!;
  return {
    n,
    k: kk,
    s,
    iterations,
    converged,
    logLik,
    aic,
    bic,
    icl,
    quality: {
      avepp,
      aveppOverall,
      entropy,
      relativeEntropy,
      classificationError,
      classEntropy,
    },
    nStarts: nStartsOut,
    restartLogLiks,
    assignments,
    responsibilities,
    pi,
    delta,
    transition,
  };
}
