/**
 * Shared state for the two loaders (load.ts = node, load-web.ts = browser).
 * Both populate `setExports(...)` after their respective wasm-pack init;
 * shim.ts consumes via `getExports()` agnostic to which path ran.
 */
import type { WasmEngineExports } from './load.js';

let _exports: WasmEngineExports | null = null;

export function setExports(e: WasmEngineExports): void {
  _exports = e;
}

export function isInitialized(): boolean {
  return _exports !== null;
}

export function getExports(): WasmEngineExports {
  if (_exports === null) {
    throw new Error('initWasmEngine has not been called (or threw)');
  }
  return _exports;
}
