/**
 * permutationTest — WASM-backed. Matches tnaj's PermutationResult shape
 * including the EdgeStat[] table.
 */
import { permutationTestWasm } from '../wasm-engine/index-pure.js';
import type { EdgeStat, PermutationOptions, PermutationResult, TNA } from '../index.js';
import { assertReady } from './assert.js';
import { integerizeModel } from './model.js';

export function permutationTest(
  x: TNA,
  y: TNA,
  options: PermutationOptions = {},
): PermutationResult {
  assertReady();
  if (!x.data || !y.data) {
    throw new Error('Both TNA models must have sequence data for permutation test');
  }
  const { iter = 1000, adjust = 'none', level = 0.05, seed = 42, paired = false } = options;

  const igX = integerizeModel(x);
  const igY = integerizeModel(y);
  if (igX.nStates !== igY.nStates) {
    throw new Error(`permutationTest: state-set mismatch (${igX.nStates} vs ${igY.nStates})`);
  }

  const r = permutationTestWasm({
    valuesX: igX.values,
    rowStartsX: igX.rowStarts,
    valuesY: igY.values,
    rowStartsY: igY.rowStarts,
    nStates: igX.nStates,
    type: x.type === 'frequency' ? 'frequency' : 'relative',
    scaling: (x.scaling as readonly ('minmax' | 'max' | 'rank')[]) ?? [],
    iter,
    seed,
    adjust,
    level,
    paired,
  });

  const n = igX.nStates;
  const edgeStats: EdgeStat[] = [];
  // Column-major iteration to match tnaj's edge ordering exactly.
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      const idx = i * n + j;
      const wx = r.originalWeightsX[idx]!;
      const wy = r.originalWeightsY[idx]!;
      if (wx === 0 && wy === 0) continue;
      edgeStats.push({
        from: igX.labels[i]!,
        to: igX.labels[j]!,
        diffTrue: r.diffTrue[idx]!,
        effectSize: r.effectSizes[idx]!,
        pValue: r.pValues[idx]!,
      });
    }
  }

  return {
    edgeStats,
    diffTrue: r.diffTrue,
    diffSig: r.diffSig,
    pValues: r.pValues,
    labels: [...igX.labels],
    nStates: n,
    level,
  };
}
