/**
 * bootstrapTna — WASM-backed. Matches tnaj's BootstrapResult shape exactly,
 * including the 11-field BootstrapEdge (from/to/weight/bootstrapMean/bias/
 * pValue/significant/crLower/crUpper/ciLower/ciUpper).
 */
import { bootstrapTnaWasm } from '../wasm-engine/index-pure.js';
import type { BootstrapEdge, BootstrapOptions, BootstrapResult, TNA } from '../index.js';
import { assertReady } from './assert.js';
import { integerizeModel } from './model.js';

export function bootstrapTna(model: TNA, options: BootstrapOptions = {}): BootstrapResult {
  assertReady();
  const {
    iter = 1000,
    level = 0.05,
    method = 'stability',
    // The pure-TS interface accepts `consistencyRange: [lo, hi]`. Keep parity.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    consistencyRange = [0.75, 1.25] as [number, number],
    threshold,
    seed = 42,
  } = options as BootstrapOptions & { consistencyRange?: [number, number]; threshold?: number; seed?: number };

  const ig = integerizeModel(model);
  const r = bootstrapTnaWasm({
    values: ig.values,
    rowStarts: ig.rowStarts,
    nStates: ig.nStates,
    type: model.type === 'frequency' ? 'frequency' : 'relative',
    scaling: (model.scaling as readonly ('minmax' | 'max' | 'rank')[]) ?? [],
    iter,
    seed,
    method,
    level,
    consistencyLo: consistencyRange[0],
    consistencyHi: consistencyRange[1],
    threshold: threshold ?? null,
  });

  const n = ig.nStates;
  const edges: BootstrapEdge[] = [];
  // Column-major iteration to match tnaj's edge ordering exactly.
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      const idx = i * n + j;
      const w = r.originalWeights[idx]!;
      if (w <= 0) continue;
      edges.push({
        from: ig.labels[i]!,
        to: ig.labels[j]!,
        weight: w,
        bootstrapMean: r.weightsMean[idx]!,
        bias: r.weightsBias[idx]!,
        pValue: r.pValues[idx]!,
        significant: r.pValues[idx]! < level,
        crLower: w * consistencyRange[0],
        crUpper: w * consistencyRange[1],
        ciLower: r.ciLower[idx]!,
        ciUpper: r.ciUpper[idx]!,
      });
    }
  }

  return {
    edges,
    model,
    labels: [...model.labels],
    method,
    iter,
    level,
    weightsMean: r.weightsMean,
    weightsSd: r.weightsSd,
    weightsBias: r.weightsBias,
  };
}
