/**
 * mmm — Mixture Markov Model clustering, WASM-backed (basic deterministic).
 *
 * **This is WASM-only. There is no tnaj TS implementation to fall back to.**
 * `MMMResult` is a NEW canonical type defined here (tnaj has none — propose
 * upstream later, per MMM-PLAN.md §5.7). Calling `mmm(...)` before
 * `initTnaw()` throws.
 *
 * Why this exists: distance-based clustering (`clusterData`) needs a dense
 * O(n²) distance matrix and hard-caps around ~9,680 sequences (see
 * `cluster.ts`). MMM is O(N·K) — it is the *structural* answer to
 * "cluster 100k sequences", not an O(n²) palliative.
 *
 * Validation contract is **deliberately different** from the 1e-10-vs-R
 * deterministic kernels (MMM-PLAN.md §0/§4): mixture labels are
 * identifiable only up to permutation and EM finds a local optimum, so
 * "same answer" is checked as ARI=1 + loglik, not element-wise params.
 * The kernel is bit-reproducible for a fixed (input, seed, init) and is
 * cross-checked against R `Nestimate:::.mmm_em` (single start, injected
 * init) — NOT stochastic seqHMM.
 */
import { mmmWasm, integerize } from '../wasm-engine/index-pure.js';
// Deep import from tnaj/core (not the 'tnaj' barrel) — same rationale as
// markov.ts: keep the tnaj-light bundle clean.
import { Matrix } from '../core/index.js';
import type { SequenceData, TNA } from '../index.js';
// `mmm`'s canonical type lives in tnaj (`src/analysis/mmm.ts`). tnaw is the
// WASM-accelerated implementation of the SAME contract, so it re-exports
// (does not redefine) the type — single source of truth, and tnajw can
// dispatch tnaw↔tnaj transparently.
import type { MmmOptions, MmmInput, MMMResult } from '../index.js';
// Shared validator so tnaw enforces the SAME guards as the tnaj TS twin
// (tnajw may dispatch to either — the errors must be identical).
import { validateMmmOptions } from '../analysis/mmm.js';
import { assertReady } from './assert.js';

export type { MmmOptions, MmmInput, MmmQuality, MMMResult } from '../index.js';

/** Sorted unique non-NA tokens. Matches R `build_mmm`:
 *  `states <- sort(unique(as.vector(mat))); states[!is.na(states)]`.
 *  Note: unlike `clusterData`, NO sentinel→NA conversion by default —
 *  R `build_mmm` treats "*"/"%" as real states (see its roxygen
 *  "Initial states" note). Recode to null *before* calling for padded data. */
function deriveLabels(seqData: SequenceData): string[] {
  const set = new Set<string>();
  for (const row of seqData) {
    for (const v of row) {
      if (v === null || v === undefined || v === '') continue;
      set.add(v);
    }
  }
  return [...set].sort();
}

/**
 * Fit a Mixture Markov Model. `data` is either sequence rows
 * (`(string|null)[][]`, wide format — positions are NOT compacted, an
 * interior NA breaks a transition pair, matching R) or a `TNA` with `.data`.
 */
export function mmm(data: MmmInput, options: MmmOptions): MMMResult {
  assertReady();
  const {
    k,
    maxIter = 200,
    tol = 1e-8,
    alpha = 0.01,
    seed = 42,
    nStarts = 1,
    initPosterior,
  } = options;
  validateMmmOptions({ k, maxIter, tol, alpha, seed, nStarts });

  let seqData: SequenceData;
  let labels: string[];
  if (Array.isArray(data)) {
    seqData = data as SequenceData;
    labels = deriveLabels(seqData);
  } else {
    const tna = data as TNA;
    if (!tna.data) throw new Error('mmm: TNA model missing data');
    seqData = tna.data as unknown as SequenceData;
    // R build_mmm on a tna object reuses data$labels as the state set.
    labels = [...tna.labels];
  }
  if (labels.length < 2) throw new Error('mmm: need at least 2 states');
  if (k > seqData.length) {
    throw new Error(`mmm: k=${k} exceeds number of sequences (${seqData.length})`);
  }

  // tnaj's MmmOptions.initPosterior is Float64Array | number[]; the WASM
  // shim wants a Float64Array (or omit for the seeded init).
  const ip =
    initPosterior == null
      ? undefined
      : initPosterior instanceof Float64Array
        ? initPosterior
        : new Float64Array(initPosterior);

  const ig = integerize(seqData, labels);
  const r = mmmWasm({
    values: ig.values,
    rowStarts: ig.rowStarts,
    nStates: labels.length,
    k,
    maxIter,
    tol,
    alpha,
    seed,
    nStarts,
    initPosterior: ip,
  });

  const s = r.s;
  const transition: Matrix[] = r.transition.map((flat) => {
    const m = Matrix.zeros(s, s);
    for (let i = 0; i < s; i++) {
      for (let j = 0; j < s; j++) m.set(i, j, flat[i * s + j]!);
    }
    return m;
  });

  return {
    k: r.k,
    assignments: r.assignments,
    responsibilities: r.responsibilities,
    pi: r.pi,
    delta: r.delta,
    transition,
    logLik: r.logLik,
    // Derived from AIC rather than recomputed: aic = -2·logLik + 2·df, so df = (aic + 2·logLik)/2.
    // Re-deriving the parameter count here would be a SECOND formula for it, free to drift from
    // the TS one — and the WASM kernel has no covariate path, so its df is the plain-MMM count
    // by construction. Rounded because it is an integer that arrived through floating point.
    df: Math.round((r.aic + 2 * r.logLik) / 2),
    aic: r.aic,
    bic: r.bic,
    icl: r.icl,
    quality: r.quality,
    iterations: r.iterations,
    converged: r.converged,
    nStarts: r.nStarts,
    restartLogLiks: r.restartLogLiks,
    labels,
    nSequences: r.n,
  };
}
