/**
 * clusterData / clusterSequences / computeDendrogram / findRepresentatives
 * — WASM-backed. Result shapes match tnaj exactly, including the `Matrix`
 * wrapper around the distance matrix and R's hclust `merge` convention.
 *
 * The heavy O(n²) all-pairs distance matrix, PAM (BUILD+SWAP), and the
 * Lance-Williams hierarchical merge all run in the Rust kernel. Only the
 * cheap post-processing that tnaj does around them (frequency maps,
 * per-cluster medoid selection, top-N ranking) stays in TS — it is O(n)
 * to O(members²) and reuses the kernel-returned distance matrix, so it
 * stays numerically identical to the pure-TS path.
 *
 * Strings cross the boundary integerized (token id per label; -1 = NA).
 * Every distance metric only tests token *equality*, so integer ids are
 * behaviourally identical to tnaj's unique string SENTINEL.
 */
import {
  clusterStringWasm,
  clusterNumericWasm,
  clusterFromDistWasm,
  integerize,
} from '../wasm-engine/index-pure.js';
import { Matrix } from '../core/index.js';
import type { ClusterResult, SequenceData, TNAData, RepresentativeResult } from '../index.js';
import { assertReady } from './assert.js';

type ClusterOptions = {
  dissimilarity?: string;
  method?: string;
  naSyms?: string[];
  weighted?: boolean;
  lambda?: number;
};

const DEFAULT_NA_SYMS = ['*', '%'];

/**
 * Dense-distance-matrix guard. PAM and hierarchical both need a full
 * n×n f64 matrix, and the WASM ABI materializes it TWICE at peak (the
 * kernel's `Vec<f64>` + the flat encoded output it's copied into), so
 * the wasm32 linear-memory cost is ≈ 16·n² bytes. wasm32 hard-caps at
 * 4 GiB; we throw well before that so an oversized input fails in O(1)
 * with a clear message instead of trapping after minutes of compute (or
 * — on the tnaj fallback path — swap-thrashing the machine).
 *
 * Budget 1.5 GB ⇒ n_max ≈ 9,680. Above that, clustering this many
 * sequences with an O(n²) algorithm is the wrong tool regardless of
 * engine: subsample-and-assign or `findRepresentatives` instead.
 */
const CLUSTER_PEAK_BYTES_BUDGET = 1.5e9;

function assertClusterableSize(n: number, what: string): void {
  const peakBytes = 16 * n * n; // ≈ 2 × (8·n²): kernel matrix + encoded output
  if (peakBytes > CLUSTER_PEAK_BYTES_BUDGET) {
    const nMax = Math.floor(Math.sqrt(CLUSTER_PEAK_BYTES_BUDGET / 16));
    throw new Error(
      `${what}: n=${n} sequences needs a dense ${(8 * n * n / 1e9).toFixed(1)} GB ` +
        `distance matrix (~${(peakBytes / 1e9).toFixed(1)} GB peak in WASM, which ` +
        `hard-caps at 4 GB). PAM/hierarchical are O(n²) memory; the safe limit ` +
        `here is ~${nMax} sequences. For larger data, cluster a representative ` +
        `subsample then assign, or use findRepresentatives.`,
    );
  }
}

/** Sorted unique non-NA tokens — a stable label set for integerize.
 *  Order is irrelevant to every metric (equality-only), but must be
 *  deterministic so q-gram keys are consistent across rows. */
function deriveLabels(seqData: SequenceData, naSyms: string[]): string[] {
  const naSet = new Set(naSyms);
  const set = new Set<string>();
  for (const row of seqData) {
    for (const v of row) {
      if (v === null || v === undefined || v === '') continue;
      if (naSet.has(v)) continue;
      set.add(v);
    }
  }
  return [...set].sort();
}

/** Pack a flat row-major n*n buffer into a tnaj `Matrix`. */
function toMatrix(flat: Float64Array, n: number): Matrix {
  const m = Matrix.zeros(n, n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) m.set(i, j, flat[i * n + j]!);
  }
  return m;
}

function isNumericData(data: unknown): data is number[][] {
  if (!Array.isArray(data) || data.length === 0) return false;
  const firstRow = data[0];
  return Array.isArray(firstRow) && firstRow.length > 0 && typeof firstRow[0] === 'number';
}

/** Internal: cluster string sequence data via the WASM kernel. */
function clusterStringData(
  seqData: SequenceData,
  k: number,
  method: string,
  options?: ClusterOptions,
): ClusterResult {
  const dissimilarity = options?.dissimilarity ?? 'hamming';
  const naSyms = options?.naSyms ?? DEFAULT_NA_SYMS;
  const weighted = options?.weighted ?? false;
  const lambda = options?.lambda ?? 1;

  if (k < 2) throw new Error('k must be >= 2');
  if (k > seqData.length) {
    throw new Error(`k=${k} exceeds number of sequences (${seqData.length})`);
  }
  assertClusterableSize(seqData.length, 'clusterData');

  const labels = deriveLabels(seqData, naSyms);
  const ig = integerize(seqData, labels, { naSyms });
  const r = clusterStringWasm({
    values: ig.values,
    rowStarts: ig.rowStarts,
    k,
    method,
    dissimilarity,
    weighted,
    lambda,
  });

  const result: ClusterResult = {
    data: seqData,
    k,
    assignments: r.assignments,
    silhouette: r.silhouette,
    sizes: r.sizes,
    method,
    distance: toMatrix(r.distance, r.n),
    dissimilarity,
  };
  if (r.merge) {
    result.merge = r.merge;
    result.heights = r.heights!;
    result.order = r.order!;
  }
  return result;
}

/**
 * Unified clustering function. Auto-detects input type:
 * - TNAData (has .sequenceData) → string distance metrics
 * - number[][] → numeric distance metrics (euclidean/manhattan)
 * - SequenceData (string[][]) → string distance metrics
 */
export function clusterData(
  data: SequenceData | TNAData | number[][],
  k: number,
  options?: ClusterOptions,
): ClusterResult {
  assertReady();
  const method = options?.method ?? 'pam';

  // Path 1: TNAData.
  if (typeof data === 'object' && data !== null && 'sequenceData' in data) {
    return clusterStringData((data as TNAData).sequenceData, k, method, options);
  }

  // Path 2: numeric data.
  if (isNumericData(data)) {
    const dissimilarity = options?.dissimilarity ?? 'euclidean';
    if (k < 2) throw new Error('k must be >= 2');
    if (k > data.length) {
      throw new Error(`k=${k} exceeds number of observations (${data.length})`);
    }
    assertClusterableSize(data.length, 'clusterData');
    const n = data.length;
    const p = data[0]!.length;
    const flat = new Float64Array(n * p);
    for (let i = 0; i < n; i++) {
      const row = data[i]!;
      for (let j = 0; j < p; j++) flat[i * p + j] = row[j]!;
    }
    const r = clusterNumericWasm({
      data: flat,
      n,
      p,
      k,
      method,
      metric: dissimilarity === 'manhattan' ? 'manhattan' : 'euclidean',
    });
    // tnaj converts numeric rows to string form for ClusterResult.data.
    const seqData: SequenceData = data.map((row) => row.map((v) => String(v)));
    const result: ClusterResult = {
      data: seqData,
      k,
      assignments: r.assignments,
      silhouette: r.silhouette,
      sizes: r.sizes,
      method,
      distance: toMatrix(r.distance, r.n),
      dissimilarity,
    };
    if (r.merge) {
      result.merge = r.merge;
      result.heights = r.heights!;
      result.order = r.order!;
    }
    return result;
  }

  // Path 3: SequenceData.
  return clusterStringData(data as SequenceData, k, method, options);
}

/** @deprecated Use clusterData() instead. */
export function clusterSequences(
  data: SequenceData | TNAData,
  k: number,
  options?: ClusterOptions,
): ClusterResult {
  return clusterData(data, k, options);
}

/**
 * Compute dendrogram data from a pre-computed distance matrix.
 * Returns merge history, heights, and leaf order (no cluster assignments).
 */
export function computeDendrogram(
  dist: Matrix,
  method = 'average',
): { merge: number[][]; heights: number[]; order: number[] } {
  assertReady();
  const n = dist.rows;
  assertClusterableSize(n, 'computeDendrogram');
  const flat = new Float64Array(n * n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) flat[i * n + j] = dist.get(i, j);
  }
  const r = clusterFromDistWasm({ dist: flat, n, k: 1, method });
  return { merge: r.merge!, heights: r.heights!, order: r.order! };
}

// ---- findRepresentatives (cheap post-processing in TS, distances in WASM) ----

/** Canonical key for a sequence: strip trailing nulls, join with US sep. */
function canonicalKey(seq: (string | null)[]): string {
  let last = -1;
  for (let i = seq.length - 1; i >= 0; i--) {
    if (seq[i] !== null && seq[i] !== undefined) {
      last = i;
      break;
    }
  }
  return seq
    .slice(0, last + 1)
    .map((v) => v ?? '\0NULL')
    .join('\x1f');
}

/** WASM helper: distance matrix (+ pam assignments) for string data. */
function wasmStringDistance(
  data: SequenceData,
  dissimilarity: string,
  naSyms: string[],
  k: number,
): { dist: Matrix; assignments: number[] } {
  assertClusterableSize(data.length, 'findRepresentatives');
  const labels = deriveLabels(data, naSyms);
  const ig = integerize(data, labels, { naSyms });
  const r = clusterStringWasm({
    values: ig.values,
    rowStarts: ig.rowStarts,
    k,
    method: 'pam',
    dissimilarity,
    weighted: false,
    lambda: 1,
  });
  return { dist: toMatrix(r.distance, r.n), assignments: r.assignments };
}

function pickTopFrequent(data: SequenceData, n: number): RepresentativeResult[] {
  const freqMap = new Map<string, { count: number; firstIdx: number }>();
  for (let i = 0; i < data.length; i++) {
    const key = canonicalKey(data[i]!);
    const existing = freqMap.get(key);
    if (existing) existing.count++;
    else freqMap.set(key, { count: 1, firstIdx: i });
  }
  const sorted = [...freqMap.values()].sort(
    (a, b) => b.count - a.count || a.firstIdx - b.firstIdx,
  );
  return sorted.slice(0, n).map(({ firstIdx }) => ({
    index: firstIdx,
    sequence: data[firstIdx]!,
    distance: 0,
  }));
}

function findMedoidRepresentatives(
  data: SequenceData,
  k: number | undefined,
  n: number | undefined,
  dissimilarity: string,
  naSyms: string[],
): RepresentativeResult[] {
  const numSeqs = data.length;

  if (k !== undefined) {
    if (k < 1) throw new Error('k must be >= 1');
    const effectiveK = Math.min(k, numSeqs);
    if (effectiveK < 2) {
      // k=1: single medoid of the whole dataset.
      const { dist } = wasmStringDistance(
        data,
        dissimilarity,
        naSyms,
        Math.min(2, numSeqs),
      );
      let bestIdx = 0;
      let bestSum = Infinity;
      for (let i = 0; i < numSeqs; i++) {
        let sum = 0;
        for (let j = 0; j < numSeqs; j++) sum += dist.get(i, j);
        if (sum < bestSum) {
          bestSum = sum;
          bestIdx = i;
        }
      }
      const meanDist = numSeqs > 1 ? bestSum / (numSeqs - 1) : 0;
      return [{ index: bestIdx, sequence: data[bestIdx]!, distance: meanDist, cluster: 1 }];
    }

    const { dist, assignments } = wasmStringDistance(
      data,
      dissimilarity,
      naSyms,
      effectiveK,
    );
    const results: RepresentativeResult[] = [];
    for (let c = 1; c <= effectiveK; c++) {
      const members = assignments
        .map((a, idx) => (a === c ? idx : -1))
        .filter((idx) => idx >= 0);
      if (members.length === 0) continue;
      let bestIdx = members[0]!;
      let bestSum = Infinity;
      for (const i of members) {
        let sum = 0;
        for (const j of members) sum += dist.get(i, j);
        if (sum < bestSum) {
          bestSum = sum;
          bestIdx = i;
        }
      }
      const meanDist = members.length > 1 ? bestSum / (members.length - 1) : 0;
      results.push({ index: bestIdx, sequence: data[bestIdx]!, distance: meanDist, cluster: c });
    }
    return results;
  }

  // No k: top-n most central sequences.
  const count = Math.min(n ?? 5, numSeqs);
  const { dist } = wasmStringDistance(data, dissimilarity, naSyms, Math.min(2, numSeqs));
  const totalDists: { index: number; totalDist: number }[] = [];
  for (let i = 0; i < numSeqs; i++) {
    let sum = 0;
    for (let j = 0; j < numSeqs; j++) sum += dist.get(i, j);
    totalDists.push({ index: i, totalDist: sum });
  }
  totalDists.sort((a, b) => a.totalDist - b.totalDist);
  return totalDists.slice(0, count).map(({ index, totalDist }) => ({
    index,
    sequence: data[index]!,
    distance: numSeqs > 1 ? totalDist / (numSeqs - 1) : 0,
  }));
}

function findFrequencyRepresentatives(
  data: SequenceData,
  k: number | undefined,
  n: number | undefined,
  dissimilarity: string,
  naSyms: string[],
): RepresentativeResult[] {
  const numSeqs = data.length;

  if (k !== undefined) {
    const effectiveK = Math.min(k, numSeqs);
    if (effectiveK < 2) {
      const freqResult = pickTopFrequent(data, 1);
      return freqResult.map((r) => ({ ...r, cluster: 1 }));
    }
    const { assignments } = wasmStringDistance(data, dissimilarity, naSyms, effectiveK);
    const results: RepresentativeResult[] = [];
    for (let c = 1; c <= effectiveK; c++) {
      const members = assignments
        .map((a, idx) => (a === c ? idx : -1))
        .filter((idx) => idx >= 0);
      if (members.length === 0) continue;
      const freqMap = new Map<string, { count: number; firstIdx: number }>();
      for (const idx of members) {
        const key = canonicalKey(data[idx]!);
        const existing = freqMap.get(key);
        if (existing) existing.count++;
        else freqMap.set(key, { count: 1, firstIdx: idx });
      }
      let bestCount = -1;
      let bestIdx = -1;
      for (const [, { count, firstIdx }] of freqMap) {
        if (count > bestCount) {
          bestCount = count;
          bestIdx = firstIdx;
        }
      }
      results.push({ index: bestIdx, sequence: data[bestIdx]!, distance: 0, cluster: c });
    }
    return results;
  }

  const count = Math.min(n ?? 5, numSeqs);
  return pickTopFrequent(data, count);
}

/**
 * Find representative sequences from the dataset (medoid or frequency
 * criterion). Distances/PAM run in WASM; selection logic mirrors tnaj.
 */
export function findRepresentatives(
  data: SequenceData,
  options?: {
    dissimilarity?: string;
    n?: number;
    k?: number;
    criterion?: 'medoid' | 'frequency';
    naSyms?: string[];
  },
): RepresentativeResult[] {
  assertReady();
  const criterion = options?.criterion ?? 'medoid';
  const dissimilarity = options?.dissimilarity ?? 'hamming';
  const naSyms = options?.naSyms ?? DEFAULT_NA_SYMS;
  const k = options?.k;

  if (data.length === 0) return [];

  if (criterion === 'frequency') {
    return findFrequencyRepresentatives(data, k, options?.n, dissimilarity, naSyms);
  }
  return findMedoidRepresentatives(data, k, options?.n, dissimilarity, naSyms);
}
