/**
 * Shared model marshaling for tnaw. Converts a tnaj `TNA` (with sequence
 * data attached) into the integerized arrays the WASM kernels accept.
 */
import { integerize } from '../wasm-engine/index-pure.js';
import type { TNA } from '../index.js';

export interface Integerized {
  values: Int32Array;
  rowStarts: Uint32Array;
  labels: readonly string[];
  nStates: number;
}

export function integerizeModel(model: TNA): Integerized {
  if (!model.data) {
    throw new Error(
      'tnaw: TNA model has no `data` attached. Call `model.data = sequences` before bootstrap/permutation/stability.',
    );
  }
  const seqs = model.data as unknown as readonly (readonly (string | null)[])[];
  const ig = integerize(seqs, model.labels);
  return {
    values: ig.values,
    rowStarts: ig.rowStarts,
    labels: ig.labels,
    nStates: ig.labels.length,
  };
}

/** Flatten a TNA's row-major weight matrix to a Float64Array of length n*n. */
export function flattenWeights(model: TNA): Float64Array {
  const n = model.labels.length;
  const out = new Float64Array(n * n);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      out[i * n + j] = model.weights.get(i, j);
    }
  }
  return out;
}
